/**
 * Component: use-scroll-effect
 * Author: @omer-fils-elenga (https://tailwindflex.com/@omer-fils-elenga)
 * Source: https://tailwindflex.com/@omer-fils-elenga/use-scroll-effect
 * Attribution: Créé par @omer-fils-elenga sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function UseScrollEffect() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="fr" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Scroll Animation Master</title>
    <!-- Tailwind CSS pour le layout rapide -->

    <!-- Police Inter pour le look moderne -->
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;700;900&display=swap" rel="stylesheet">

    <style>
        :root {
            --anim-speed: 0.8s;
            --anim-curve: cubic-bezier(0.16, 1, 0.3, 1); /* Curve très fluide */
        }

        body {
            font-family: 'Inter', sans-serif;
            background-color: #050505;
            color: #ffffff;
            overflow-x: hidden;
        }

        /* --- 1. LOGIQUE DE BASE DES ANIMATIONS --- */
        .reveal-section {
            opacity: 0;
            transition: transform var(--anim-speed) var(--anim-curve), 
                        opacity var(--anim-speed) var(--anim-curve);
            will-change: transform, opacity;
        }

        /* États initiaux selon la direction (Définis par data-direction) */
        .reveal-section[data-direction="top"] { transform: translateY(-60px); }
        .reveal-section[data-direction="bottom"] { transform: translateY(60px); }
        .reveal-section[data-direction="left"] { transform: translateX(-60px); }
        .reveal-section[data-direction="right"] { transform: translateX(60px); }

        /* Quand la section est visible (ajouté par JS) */
        .reveal-section.is-visible {
            opacity: 1;
            transform: translate(0, 0);
        }

        /* --- 2. ANIMATION DU CONTENU (Enfant) --- */
        .reveal-content {
            opacity: 0;
            transition: transform 0.6s var(--anim-curve), opacity 0.6s var(--anim-curve);
            transition-delay: 0.1s; /* Petit délai après le conteneur */
        }

        .reveal-content[data-direction="top"] { transform: translateY(-40px); }
        .reveal-content[data-direction="bottom"] { transform: translateY(40px); }
        .reveal-content[data-direction="left"] { transform: translateX(-40px); }
        .reveal-content[data-direction="right"] { transform: translateX(40px); }

        .reveal-section.is-visible .reveal-content {
            opacity: 1;
            transform: translate(0, 0);
        }


        /* --- 3. EFFET FOCUS (HOVER) --- */
        /* Quand on est en mode focus (souris sur une section) */
        body.is-hovering .reveal-section:not(:hover) {
            opacity: 0.1; /* Les autres sections disparaissent presque */
            filter: blur(4px);
            transform: scale(0.95) !important; /* Rétrécissent */
            transition: all 0.5s var(--anim-curve);
        }

        body.is-hovering .reveal-section:hover {
            transform: scale(1.02) !important; /* La section active grandit */
            z-index: 10;
            transition: all 0.5s var(--anim-curve);
        }

        /* --- 4. PAGINATION (SIDE NAV) --- */
        #pagination-nav {
            position: fixed;
            right: 20px;
            top: 50%;
            transform: translateY(-50%);
            z-index: 50;
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .nav-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background-color: #333;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot:hover {
            background-color: #fff;
        }

        .nav-dot.active {
            background-color: #fff;
            transform: scale(1.5);
            box-shadow: 0 0 10px rgba(255,255,255,0.5);
        }

        /* --- UTILITAIRES VISUELS --- */
        .glass-panel {
            background: rgba(255, 255, 255, 0.05);
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.1);
        }
    </style>
</head>
<body>

    <!-- PAGINATION (Créée automatiquement par le JS) -->
    <nav id="pagination-nav"></nav>

    <!-- SECTION 1: HERO (Texte du Haut) -->
    <section class="min-h-screen flex items-center justify-center px-6 reveal-section" data-direction="bottom" id="hero">  
        <div class="max-w-4xl text-center">
            <p class="text-indigo-500 font-bold tracking-widest mb-4 reveal-content" data-direction="bottom">INTRODUCTION</p>
            <h1 class="text-6xl md:text-9xl font-black tracking-tighter mb-6 reveal-content" data-direction="top">
                Design <br><span class="text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-cyan-400">Intelligent.</span>
            </h1>
            <p class="text-gray-400 text-lg md:text-xl max-w-2xl mx-auto reveal-content" data-direction="bottom">
                Une expérience fluide, réactive et élégante. Scrollez vers le bas pour voir la magie opérer.
            </p>
        </div>
    </section>

    <!-- SECTION 2: GAUCHE DROITE -->
    <section class="min-h-screen flex items-center px-6 py-20 reveal-section" data-direction="left" id="features">
        <div class="max-w-6xl mx-auto w-full grid md:grid-cols-2 gap-16 items-center">

            <!-- Contenu Texte (Venant de la gauche) -->
            <div class="reveal-content" data-direction="left">
                <h2 class="text-4xl md:text-5xl font-bold mb-6">Gestion intelligente</h2>
                <p class="text-gray-400 text-lg leading-relaxed mb-8">
                    Notre script détecte automatiquement la direction de votre entrée. Que vous veniez d'en haut ou d'en bas, l'animation s'adapte.
                </p>
                <button class="bg-white text-black px-8 py-4 rounded-full font-bold hover:scale-105 transition transform">
                    Découvrir le code
                </button>
            </div>

            <!-- Visuel (Venant de la droite) -->
            <div class="h-[400px] glass-panel rounded-3xl relative overflow-hidden reveal-content" data-direction="right">
                <img src="https://images.unsplash.com/photo-1550751827-4bd374c3f58b?q=80&w=1000" class="w-full h-full object-cover opacity-80 hover:scale-110 transition duration-700">
            </div>

        </div>
    </section>

    <!-- SECTION 3: DROITE GAUCHE -->
    <section class="min-h-screen flex items-center px-6 py-20 reveal-section" data-direction="right" id="about">
        <div class="max-w-6xl mx-auto w-full grid md:grid-cols-2 gap-16 items-center">

            <!-- Visuel (Venant de la gauche) -->
            <div class="h-[400px] glass-panel rounded-3xl relative overflow-hidden order-2 md:order-1 reveal-content" data-direction="left">
                <img src="https://images.unsplash.com/photo-1519389950473-47ba0277781c?q=80&w=1000" class="w-full h-full object-cover opacity-80 hover:scale-110 transition duration-700">
            </div>

            <!-- Contenu Texte (Venant de la droite) -->
            <div class="order-1 md:order-2 reveal-content" data-direction="right">
                <h2 class="text-4xl md:text-5xl font-bold mb-6">Performance pure</h2>
                <p class="text-gray-400 text-lg leading-relaxed mb-8">
                    Utilisation de l'API `IntersectionObserver` native. Aucune librairie lourde, juste du JavaScript pur optimisé pour 60fps.
                </p>
                <div class="flex gap-4">
                    <div class="bg-gray-900 p-4 rounded-xl border border-gray-800">
                        <div class="text-2xl font-bold text-indigo-400">0ms</div>
                        <div class="text-xs text-gray-500 uppercase">Latence</div>
                    </div>
                    <div class="bg-gray-900 p-4 rounded-xl border border-gray-800">
                        <div class="text-2xl font-bold text-green-400">100%</div>
                        <div class="text-xs text-gray-500 uppercase">Compatibilité</div>
                    </div>
                </div>
            </div>

        </div>
    </section>

    <!-- SECTION 4: BAS (FOOTER) -->
    <section class="min-h-[50vh] flex flex-col items-center justify-center px-6 py-20 reveal-section" data-direction="bottom" id="footer">
        <h2 class="text-5xl md:text-8xl font-black mb-8 reveal-content" data-direction="bottom">Start Now.</h2>
        <a href="#" class="text-xl underline text-gray-400 hover:text-white transition reveal-content" data-direction="top">omerlinkStream © 2026</a>
    </section>

    <!-- SCRIPT JAVASCRIPT PRINCIPAL -->

</body>
</html>" }} />
  );
}
